{"file_path":"src/address.js","content":"/** Cell addresses: one or two letters for the column, one to three digits for
 * the row. Columns run A..Z then AA..ZZ, rows start at 1. */

const ADDRESS_RE = /^[A-Za-z]{1,2}[0-9]{1,3}$/

/** Parses a word as an address, returning { key, col, row } or null when the
 * word does not name a cell inside the addressable range. */
export function parseAddress(word) {
  if (!ADDRESS_RE.test(word)) return null
  const upper = word.toUpperCase()
  const letters = upper.match(/^[A-Z]+/)[0]
  const digits = upper.slice(letters.length)
  const row = Number(digits)
  if (row < 1) return null
  const col =
    letters.length === 1
      ? letters.charCodeAt(0) - 65
      : (letters.charCodeAt(0) - 64) * 26 + (letters.charCodeAt(1) - 65)
  return { key: upper, col, row }
}

/** The canonical text of a column index. */
export function columnName(col) {
  if (col < 26) return String.fromCharCode(65 + col)
  const first = Math.floor(col / 26)
  return String.fromCharCode(64 + first) + String.fromCharCode(65 + (col % 26))
}

export function addressKey(col, row) {
  return columnName(col) + String(row)
}

/** Orders cells by column and then by row. */
export function compareCells(a, b) {
  return a.col - b.col || a.row - b.row
}
"}

