{"file_path":"src/values.js","content":"/** Sheet values: numbers, text, booleans and errors. */

export const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (v) => ({ kind: 'number', value: v })
export const text = (v) => ({ kind: 'text', value: v })
export const bool = (v) => ({ kind: 'boolean', value: v })
export const err = (token) => ({ kind: 'error', value: token })

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME = err('#NAME?')
export const ERR = err('#ERR!')

export const isError = (v) => v.kind === 'error'

/** Reads a value as a number; booleans count as 1 and 0 and text does not
 * convert. Returns an error value or null in `error`. */
export function toNumber(v) {
  switch (v.kind) {
    case 'number':
      return { error: null, value: v.value }
    case 'boolean':
      return { error: null, value: v.value ? 1 : 0 }
    case 'text':
      return { error: VALUE, value: 0 }
    default:
      return { error: v, value: 0 }
  }
}

/** A finite number, or the division error for anything else. */
export function finite(n) {
  return Number.isFinite(n) ? num(n) : DIV0
}

function compareText(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i++) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length === right.length ? 0 : left.length < right.length ? -1 : 1
}

const RANK = { number: 0, text: 1, boolean: 2 }

/** Orders two non-error values: numbers below text below booleans. */
export function compareValues(a, b) {
  if (a.kind !== b.kind) return RANK[a.kind] < RANK[b.kind] ? -1 : 1
  if (a.kind === 'text') return compareText(a.value, b.value)
  const x = a.kind === 'boolean' ? (a.value ? 1 : 0) : a.value
  const y = b.kind === 'boolean' ? (b.value ? 1 : 0) : b.value
  return x === y ? 0 : x < y ? -1 : 1
}

/** How a value is printed. */
export function formatValue(v) {
  switch (v.kind) {
    case 'number':
      return formatNumber(v.value)
    case 'boolean':
      return v.value ? 'TRUE' : 'FALSE'
    default:
      return v.value
  }
}

/** Numbers print as JavaScript prints them once rounded to ten significant
 * digits. */
export function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}
"}

