{"file_path":"src/formula.js","content":"/** The formula grammar: a lexer and a recursive descent parser producing an
 * abstract syntax tree. A parse failure throws `ParseError`. */

export class ParseError extends Error {}

const fail = () => {
  throw new ParseError('bad formula')
}

const isDigit = (c) => c >= '0' && c <= '9'
const isLetter = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')

const TWO_CHAR = ['<=', '>=', '<>']
const ONE_CHAR = '^*/+-=<>(),:'

export function lex(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const c = source[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (isDigit(c)) {
      let j = i
      while (j < source.length && isDigit(source[j])) j++
      if (source[j] === '.') {
        j++
        if (!isDigit(source[j])) fail()
        while (j < source.length && isDigit(source[j])) j++
      }
      tokens.push({ type: 'number', text: source.slice(i, j) })
      i = j
      continue
    }
    if (isLetter(c)) {
      let j = i
      while (j < source.length && isLetter(source[j])) j++
      while (j < source.length && isDigit(source[j])) j++
      tokens.push({ type: 'word', text: source.slice(i, j) })
      i = j
      continue
    }
    const pair = source.slice(i, i + 2)
    if (TWO_CHAR.includes(pair)) {
      tokens.push({ type: 'op', text: pair })
      i += 2
      continue
    }
    if (ONE_CHAR.includes(c)) {
      tokens.push({ type: 'op', text: c })
      i++
      continue
    }
    fail()
  }
  return tokens
}

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek(offset = 0) {
    return this.tokens[this.at + offset]
  }

  isOp(text, offset = 0) {
    const token = this.peek(offset)
    return token !== undefined && token.type === 'op' && token.text === text
  }

  take() {
    return this.tokens[this.at++]
  }

  expectOp(text) {
    if (!this.isOp(text)) fail()
    this.at++
  }

  parseExpression() {
    let left = this.parseAdditive()
    while (this.peek() && this.peek().type === 'op' && COMPARISONS.includes(this.peek().text)) {
      const op = this.take().text
      left = { type: 'binary', op, left, right: this.parseAdditive() }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.isOp('+') || this.isOp('-')) {
      const op = this.take().text
      left = { type: 'binary', op, left, right: this.parseMultiplicative() }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.isOp('*') || this.isOp('/')) {
      const op = this.take().text
      left = { type: 'binary', op, left, right: this.parsePower() }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.isOp('^')) {
      this.at++
      return { type: 'binary', op: '^', left: base, right: this.parsePower() }
    }
    return base
  }

  parseUnary() {
    if (this.isOp('-') || this.isOp('+')) {
      const op = this.take().text
      return { type: 'unary', op, operand: this.parseUnary() }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (token === undefined) fail()
    if (token.type === 'number') {
      this.at++
      return { type: 'number', value: Number(token.text) }
    }
    if (token.type === 'word') {
      if (this.isOp('(', 1)) {
        this.at += 2
        const args = []
        if (!this.isOp(')')) {
          args.push(this.parseExpression())
          while (this.isOp(',')) {
            this.at++
            args.push(this.parseExpression())
          }
        }
        this.expectOp(')')
        return { type: 'call', name: token.text.toUpperCase(), args }
      }
      if (this.isOp(':', 1)) {
        const end = this.peek(2)
        if (end === undefined || end.type !== 'word') fail()
        this.at += 3
        return { type: 'range', from: token.text, to: end.text }
      }
      this.at++
      return { type: 'word', name: token.text }
    }
    if (this.isOp('(')) {
      this.at++
      const inner = this.parseExpression()
      this.expectOp(')')
      return inner
    }
    return fail()
  }
}

/** Parses a formula body. Throws `ParseError` when the grammar rejects it. */
export function parseFormula(body) {
  const parser = new Parser(lex(body))
  const tree = parser.parseExpression()
  if (parser.at !== parser.tokens.length) fail()
  return tree
}

/** Whether every range in the tree sits directly in an argument position. */
export function rangesWellPlaced(node) {
  switch (node.type) {
    case 'range':
      return false
    case 'call':
      return node.args.every((arg) => arg.type === 'range' || rangesWellPlaced(arg))
    case 'binary':
      return rangesWellPlaced(node.left) && rangesWellPlaced(node.right)
    case 'unary':
      return rangesWellPlaced(node.operand)
    default:
      return true
  }
}
"}

