{"file_path":"src/sheet.js","content":"/** Reading a sheet: one cell per line, an address then its content. */

import { parseAddress } from './address.js'

export class SheetError extends Error {}

/** Splits the input into lines, dropping the empty tail a trailing newline
 * leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Parses the sheet, returning a Map from address to
 * { key, col, row, content }. Throws `SheetError` on the first bad line. */
export function parseSheet(input) {
  const cells = new Map()
  const lines = splitLines(input)
  for (let index = 0; index < lines.length; index++) {
    const number = index + 1
    const line = lines[index].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue
    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const word = line.slice(0, end)
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) rest++
    const content = line.slice(rest)
    const address = parseAddress(word)
    if (address === null) {
      throw new SheetError(`line ${number}: invalid cell address ${word.toUpperCase()}`)
    }
    if (cells.has(address.key)) {
      throw new SheetError(`line ${number}: cell ${address.key} is declared twice`)
    }
    cells.set(address.key, { ...address, content })
  }
  return cells
}
"}

