{"file_path":"src/workbook.js","content":"/** Evaluating a sheet: cell values and the cells each formula names. */

import { addressKey, compareCells, parseAddress } from './address.js'
import { ParseError, parseFormula, rangesWellPlaced } from './formula.js'
import {
  CYCLE,
  DIV0,
  ERR,
  ERRORS,
  NAME,
  REF,
  VALUE,
  bool,
  compareValues,
  finite,
  isError,
  num,
  text,
  toNumber,
} from './values.js'

const NUMBER_LITERAL = /^-?[0-9]+(\.[0-9]+)?$/

/** The value of a cell whose content is not a formula. */
export function literalValue(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL.test(content)) return num(Number(content))
  if (ERRORS.includes(content)) return { kind: 'error', value: content }
  return text(content)
}

const ARITY = {
  SUM: 'many',
  MIN: 'many',
  MAX: 'many',
  COUNT: 'many',
  AVG: 'many',
  ABS: 1,
  IF: 3,
}

export class Workbook {
  constructor(cells) {
    this.cells = cells
    this.compiled = new Map()
    this.values = new Map()
    this.active = new Set()
  }

  /** The parsed form of a declared cell's content. */
  compile(key) {
    if (this.compiled.has(key)) return this.compiled.get(key)
    const cell = this.cells.get(key)
    let result
    if (!cell.content.startsWith('=')) {
      result = { kind: 'literal', value: literalValue(cell.content) }
    } else {
      try {
        const tree = parseFormula(cell.content.slice(1))
        result = { kind: 'formula', tree, wellPlaced: rangesWellPlaced(tree) }
      } catch (error) {
        if (!(error instanceof ParseError)) throw error
        result = { kind: 'invalid' }
      }
    }
    this.compiled.set(key, result)
    return result
  }

  /** The value of any cell; one nobody declared is the number 0. */
  valueOf(key) {
    if (!this.cells.has(key)) return num(0)
    if (this.values.has(key)) return this.values.get(key)
    if (this.active.has(key)) return CYCLE
    this.active.add(key)
    let value
    try {
      const compiled = this.compile(key)
      if (compiled.kind === 'literal') value = compiled.value
      else if (compiled.kind === 'invalid' || !compiled.wellPlaced) value = ERR
      else value = this.evaluate(compiled.tree)
    } finally {
      this.active.delete(key)
    }
    this.values.set(key, value)
    return value
  }

  evaluate(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'word':
        return this.word(node.name)
      case 'unary':
        return this.unary(node)
      case 'binary':
        return this.binary(node)
      case 'call':
        return this.call(node)
      default:
        return ERR
    }
  }

  word(name) {
    const upper = name.toUpperCase()
    if (upper === 'TRUE') return bool(true)
    if (upper === 'FALSE') return bool(false)
    const address = parseAddress(name)
    if (address === null) return REF
    return this.valueOf(address.key)
  }

  unary(node) {
    const operand = toNumber(this.evaluate(node.operand))
    if (operand.error) return operand.error
    return finite(node.op === '-' ? -operand.value : operand.value)
  }

  binary(node) {
    const op = node.op
    if (op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>=') {
      const left = this.evaluate(node.left)
      if (isError(left)) return left
      const right = this.evaluate(node.right)
      if (isError(right)) return right
      const order = compareValues(left, right)
      switch (op) {
        case '=':
