    return this.valueOf(address.key)
  }

  unary(node) {
    const operand = toNumber(this.evaluate(node.operand))
    if (operand.error) return operand.error
    return finite(node.op === '-' ? -operand.value : operand.value)
  }

  binary(node) {
    const op = node.op
    if (op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>=') {
      const left = this.evaluate(node.left)
      if (isError(left)) return left
      const right = this.evaluate(node.right)
      if (isError(right)) return right
      const order = compareValues(left, right)
      switch (op) {
        case '=':
          return bool(order === 0)
        case '<>':
          return bool(order !== 0)
        case '<':
          return bool(order < 0)
        case '<=':
          return bool(order <= 0)
        case '>':
          return bool(order > 0)
        default:
          return bool(order >= 0)
      }
    }
    const left = toNumber(this.evaluate(node.left))
    if (left.error) return left.error
    const right = toNumber(this.evaluate(node.right))
    if (right.error) return right.error
    switch (op) {
      case '+':
        return finite(left.value + right.value)
      case '-':
        return finite(left.value - right.value)
      case '*':
        return finite(left.value * right.value)
      case '/':
        if (right.value === 0) return DIV0
        return finite(left.value / right.value)
      default:
        return finite(left.value ** right.value)
    }
  }

  /** The values an argument contributes: a range contributes every cell it
   * covers, anything else the one value it is. */
  argumentValues(node) {
    if (node.type !== 'range') return [this.evaluate(node)]
    const cells = rangeCells(node)
    if (cells === null) return [REF]
    return cells.map((cell) => this.valueOf(cell.key))
  }

  call(node) {
    const arity = ARITY[node.name]
    if (arity === undefined) return NAME
    if (arity === 'many' ? node.args.length < 1 : node.args.length !== arity) return ERR
    if (node.name === 'IF') return this.callIf(node)
    const values = []
    for (const arg of node.args) values.push(...this.argumentValues(arg))
    for (const value of values) if (isError(value)) return value
    if (node.name === 'COUNT') {
      return num(values.filter((value) => value.kind === 'number').length)
    }
    const numbers = []
    for (const value of values) {
      const read = toNumber(value)
      if (read.error) return read.error
      numbers.push(read.value)
    }
    switch (node.name) {
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      case 'SUM':
        return finite(numbers.reduce((a, b) => a + b, 0))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
      case 'MIN':
        return finite(Math.min(...numbers))
      default:
        return finite(Math.max(...numbers))
    }
  }

  /** IF reads its condition and returns only the branch it takes. */
  callIf(node) {
    const conditions = this.argumentValues(node.args[0])
    for (const value of conditions) if (isError(value)) return value
    const condition = conditions[0]
    let taken
    if (condition === undefined) return ERR
    if (condition.kind === 'boolean') taken = condition.value
    else if (condition.kind === 'number') taken = condition.value !== 0
    else return VALUE
    const values = this.argumentValues(node.args[taken ? 1 : 2])
    for (const value of values) if (isError(value)) return value
    return values[0] === undefined ? ERR : values[0]
  }
}

/** The cells a range covers, in ascending column and then row order, whichever
 * corner it was written from; null when a corner is out of range. */
export function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const cells = []
  const lowCol = Math.min(from.col, to.col)
  const highCol = Math.max(from.col, to.col)
  const lowRow = Math.min(from.row, to.row)
  const highRow = Math.max(from.row, to.row)
  for (let col = lowCol; col <= highCol; col++) {
    for (let row = lowRow; row <= highRow; row++) {
      cells.push({ key: addressKey(col, row), col, row })
    }
  }
  return cells
}

/** The distinct cells a declared cell's content names directly, ordered by
 * column and then by row. */
export function dependencies(workbook, key) {
  const compiled = workbook.compile(key)
  if (compiled.kind !== 'formula') return []
  const found = new Map()
  const visit = (node) => {
    switch (node.type) {
      case 'word': {
        const upper = node.name.toUpperCase()
        if (upper === 'TRUE' || upper === 'FALSE') return
        const address = parseAddress(node.name)
        if (address !== null) found.set(address.key, address)
        return
      }
      case 'range': {
        const cells = rangeCells(node)
        if (cells !== null) for (const cell of cells) found.set(cell.key, cell)
        return
      }
      case 'call':
        node.args.forEach(visit)
        return
      case 'binary':
        visit(node.left)
        visit(node.right)
        return
      case 'unary':
        visit(node.operand)
    }
  }
  visit(compiled.tree)
  return [...found.values()].sort(compareCells)
}
"}

