{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { compareCells } from './address.js'
import { SheetError, parseSheet } from './sheet.js'
import { formatValue } from './values.js'
import { Workbook, dependencies } from './workbook.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'values' && mode !== 'deps') {
    process.stderr.write('error: usage: cli.js values|deps\n')
    return 2
  }
  let cells
  try {
    cells = parseSheet(readStdin())
  } catch (error) {
    if (!(error instanceof SheetError)) throw error
    process.stderr.write(`error: ${error.message}\n`)
    return 2
  }
  const workbook = new Workbook(cells)
  const ordered = [...cells.values()].sort(compareCells)
  let out = ''
  for (const cell of ordered) {
    if (mode === 'values') {
      out += `${cell.key}=${formatValue(workbook.valueOf(cell.key))}\n`
    } else {
      const named = dependencies(workbook, cell.key)
      out += `${cell.key}:${named.map((dep) => ` ${dep.key}`).join('')}\n`
    }
  }
  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))
"}

